1	// Package calibrate 是本地器具校准与证书的本地台账。
2	//
3	// 台账只保存在本机指定文件中，不连接任何真实实验室。多次打开同一文件
4	// 可以继续查询与操作，不同文件之间的数据互不相干。
5	package calibrate
6	
7	import (
8		"encoding/json"
9		"errors"
10		"fmt"
11		"math"
12		"os"
13		"path/filepath"
14		"sort"
15		"strings"
16		"time"
17	)
18	
19	// 日期布局，所有入参日期都必须是实际存在的 YYYY-MM-DD。
20	const DateLayout = "2006-01-02"
21	
22	// Status 是器具的运行状态。
23	type Status string
24	
25	const (
26		// StatusPending 表示待校准，新登记器具的初始状态。
27		StatusPending Status = "待校准"
28		// StatusInUse 表示在用；在用本身不代表已经校准。
29		StatusInUse Status = "在用"
30		// StatusRetired 表示停用；停用不删除证书与使用记录。
31		StatusRetired Status = "停用"
32	)
33	
34	// ParseStatus 把命令行或文件中的状态文本解析为 Status。
35	func ParseStatus(s string) (Status, error) {
36		switch strings.TrimSpace(s) {
37		case string(StatusPending), "pending":
38			return StatusPending, nil
39		case string(StatusInUse), "in-use", "in_use":
40			return StatusInUse, nil
41		case string(StatusRetired), "retired":
42			return StatusRetired, nil
43		default:
44			return "", fmt.Errorf("无效状态 %q：只能是 在用、停用 或 待校准", s)
45		}
46	}
47	
48	// Instrument 是登记的器具信息。
49	type Instrument struct {
50		ID           string  `json:"id"`
51		Name         string  `json:"name"`
52		AllowedError float64 `json:"allowed_error"`
53		Status       Status  `json:"status"`
54		RegisteredAt string  `json:"registered_at"`
55	}
56	
57	// Certificate 是一张校准证书。
58	type Certificate struct {
59		Number       string  `json:"number"`
60		InstrumentID string  `json:"instrument_id"`
61		CalDate      string  `json:"cal_date"`
62		Expiry       string  `json:"expiry"`
63		Method       string  `json:"method"`
64		Error        float64 `json:"error"`
65		Summary      string  `json:"summary"`
66		CreatedAt    string  `json:"created_at"`
67	}
68	
69	// Pass 按证书自身数据判断是否合格：测得误差绝对值不超过允许误差（含限值）。
70	// 结论由数据计算，录入者不能自行选择。
71	func (c Certificate) Pass(allowedError float64) bool {
72		return math.Abs(c.Error) <= allowedError
73	}
74	
75	// UsageRecord 是一次使用申请的留痕，原因在申请发生时冻结。
76	type UsageRecord struct {
77		InstrumentID string   `json:"instrument_id"`
78		RequestedAt  string   `json:"requested_at"`
79		Allowed      bool     `json:"allowed"`
80		Reasons      []string `json:"reasons"`
81	}
82	
83	// ledgerData 是台账文件的持久化结构。
84	type ledgerData struct {
85		Version      int           `json:"version"`
86		Instruments  []Instrument  `json:"instruments"`
87		Certificates []Certificate `json:"certificates"`
88		Usage        []UsageRecord `json:"usage"`
89	}
90	
91	// Ledger 是一份可操作的本地台账。
92	type Ledger struct {
93		path string
94		now  func() time.Time
95		data ledgerData
96	}
97	
98	// ValidationError 表示输入未通过业务校验，调用方不会改动任何已有记录。
99	type ValidationError struct{ Msg string }
100	
101	func (e *ValidationError) Error() string { return e.Msg }
102	
103	func validationError(format string, args ...any) error {
104		return &ValidationError{Msg: fmt.Sprintf(format, args...)}
105	}
106	
107	// IsValidation 报告 err 是否为业务校验错误。
108	func IsValidation(err error) bool {
109		var v *ValidationError
110		return errors.As(err, &v)
111	}
112	
113	// ConflictError 表示同号证书内容不一致等冲突，已有数据保持不变。
114	type ConflictError struct{ Msg string }
115	
116	func (e *ConflictError) Error() string { return e.Msg }
117	
118	// IsConflict 报告 err 是否为冲突错误。
119	func IsConflict(err error) bool {
120		var c *ConflictError
121		return errors.As(err, &c)
122	}
123	
124	// ErrNotFound 表示编号在台账中不存在。
125	var ErrNotFound = errors.New("记录不存在")
126	
127	func cleanText(s string) (string, error) {
128		t := strings.TrimSpace(s)
129		if t == "" {
130			return "", validationError("不能留空或只有空白")
131		}
132		return t, nil
133	}
134	
135	func parseFiniteDate(s, field string) (time.Time, string, error) {
136		t := strings.TrimSpace(s)
137		if t == "" {
138			return time.Time{}, "", validationError("%s不能留空", field)
139		}
140		parsed, err := time.Parse(DateLayout, t)
141		if err != nil {
142			return time.Time{}, "", validationError("%s必须是实际存在的日期（格式 YYYY-MM-DD）", field)
143		}
144		// time.Parse 对 YYYY-MM-DD 遇到超范围日期会直接报错；再用 Format
145		// 往返一次，拒绝 2024-2-3 之类格式不符的输入。
146		if parsed.Format(DateLayout) != t {
147			return time.Time{}, "", validationError("%s必须是实际存在的日期（格式 YYYY-MM-DD）", field)
148		}
149		return parsed, t, nil
150	}
151	
152	func finiteNumber(v float64, field string) error {
153		if math.IsNaN(v) || math.IsInf(v, 0) {
154			return validationError("%s必须是有限数", field)
155		}
156		return nil
157	}
158	
159	// Open 打开 path 所指的本机台账；文件不存在时建立一份新台账。
160	// 同一文件可以反复打开继续操作，不同 path 的数据互不混入。
161	func Open(path string) (*Ledger, error) {
162		return openAt(path, time.Now)
163	}
164	
165	func openAt(path string, now func() time.Time) (*Ledger, error) {
166		if strings.TrimSpace(path) == "" {
167			return nil, fmt.Errorf("台账文件路径不能为空")
168		}
169		l := &Ledger{
170			path: path,
171			now:  now,
172			data: ledgerData{Version: 1},
173		}
174		raw, err := os.ReadFile(path)
175		if err != nil {
176			if errors.Is(err, os.ErrNotExist) {
177				return l, nil
178			}
179			return nil, fmt.Errorf("读取台账 %s: %w", path, err)
180		}
181		if len(raw) > 0 {
182			if err := json.Unmarshal(raw, &l.data); err != nil {
183				return nil, fmt.Errorf("台账文件 %s 已损坏: %w", path, err)
184			}
185		}
186		if l.data.Version == 0 {
187			l.data.Version = 1
188		}
189		return l, nil
190	}
191	
192	// Path 返回台账文件位置。
193	func (l *Ledger) Path() string { return l.path }
194	
195	// save 把当前台账完整写回文件：先写临时文件再原子改名，
196	// 保证无效录入中断时不会留下半份记录。
197	func (l *Ledger) save() error {
198		if err := os.MkdirAll(filepath.Dir(l.path), 0o755); err != nil {
199			return fmt.Errorf("创建台账目录: %w", err)
200		}
201		raw, err := json.MarshalIndent(l.data, "", "  ")
202		if err != nil {
203			return fmt.Errorf("序列化台账: %w", err)
204		}
205		raw = append(raw, '\n')
206		tmp, err := os.CreateTemp(filepath.Dir(l.path), ".ledger-*.tmp")
207		if err != nil {
208			return fmt.Errorf("创建临时台账: %w", err)
209		}
210		tmpName := tmp.Name()
211		defer os.Remove(tmpName)
212		if _, err := tmp.Write(raw); err != nil {
213			tmp.Close()
214			return fmt.Errorf("写入临时台账: %w", err)
215		}
216		if err := tmp.Close(); err != nil {
217			return fmt.Errorf("关闭临时台账: %w", err)
218		}
219		if err := os.Rename(tmpName, l.path); err != nil {
220			return fmt.Errorf("替换台账文件: %w", err)
221		}
222		return nil
223	}
224	
225	func (l *Ledger) findInstrument(id string) *Instrument {
226		for i := range l.data.Instruments {
227			if l.data.Instruments[i].ID == id {
228				return &l.data.Instruments[i]
229			}
230		}
231		return nil
232	}
233	
234	func (l *Ledger) findCertificate(number string) *Certificate {
235		for i := range l.data.Certificates {
236			if l.data.Certificates[i].Number == number {
237				return &l.data.Certificates[i]
238			}
239		}
240		return nil
241	}
242	
243	// RegisterInput 是登记器具的输入。
244	type RegisterInput struct {
245		ID           string
246		Name         string
247		AllowedError float64
248	}
249	
250	// Register 登记一件新器具。编号、名称不得为空白，允许误差必须是不小于零的
251	// 有限数；编号重复或输入无效时明确拒绝，原记录不变。新器具处于待校准状态。
252	func (l *Ledger) Register(in RegisterInput) (*Instrument, error) {
253		id, err := cleanText(in.ID)
254		if err != nil {
255			return nil, fmt.Errorf("器具编号无效：%w", err)
256		}
257		name, err := cleanText(in.Name)
258		if err != nil {
259			return nil, fmt.Errorf("器具名称无效：%w", err)
260		}
261		if err := finiteNumber(in.AllowedError, "允许的绝对误差"); err != nil {
262			return nil, err
263		}
264		if in.AllowedError < 0 {
265			return nil, validationError("允许的绝对误差不能小于零")
266		}
267		if l.findInstrument(id) != nil {
268			return nil, validationError("器具编号 %s 已存在，编号必须唯一", id)
269		}
270		inst := Instrument{
271			ID:           id,
272			Name:         name,
273			AllowedError: in.AllowedError,
274			Status:       StatusPending,
275			RegisteredAt: l.now().Format(time.RFC3339),
276		}
277		l.data.Instruments = append(l.data.Instruments, inst)
278		if err := l.save(); err != nil {
279			return nil, err
280		}
281		return &inst, nil
282	}
283	
284	// SetStatus 切换器具状态。切换为在用不代表已校准；停用不删除证书与使用记录。
285	func (l *Ledger) SetStatus(id string, status Status) error {
286		switch status {
287		case StatusInUse, StatusRetired, StatusPending:
288		default:
289			return validationError("无效状态：只能是 在用、停用 或 待校准")
290		}
291		inst := l.findInstrument(id)
292		if inst == nil {
293			return fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
294		}
295		if inst.Status == status {
296			return nil
297		}
298		inst.Status = status
299		return l.save()
300	}
301	
302	// CertificateInput 是录入校准证书的输入。
303	type CertificateInput struct {
304		InstrumentID string
305		Number       string
306		CalDate      string
307		Expiry       string
308		Method       string
309		Error        float64
310		Summary      string
311	}
312	
313	// AddCertificate 录入一张校准证书并返回它；若同号证书且全部业务字段一致，
314	// 返回原证书且不增加历史（幂等）。同号内容不同报冲突且不改动已有数据。
315	func (l *Ledger) AddCertificate(in CertificateInput) (*Certificate, bool, error) {
316		instID, err := cleanText(in.InstrumentID)
317		if err != nil {
318			return nil, false, fmt.Errorf("器具编号无效：%w", err)
319		}
320		number, err := cleanText(in.Number)
321		if err != nil {
322			return nil, false, fmt.Errorf("证书编号无效：%w", err)
323		}
324		method, err := cleanText(in.Method)
325		if err != nil {
326			return nil, false, fmt.Errorf("校准方法无效：%w", err)
327		}
328		summary, err := cleanText(in.Summary)
329		if err != nil {
330			return nil, false, fmt.Errorf("摘要无效：%w", err)
331		}
332		if err := finiteNumber(in.Error, "测得误差"); err != nil {
333			return nil, false, err
334		}
335	
336		inst := l.findInstrument(instID)
337		if inst == nil {
338			return nil, false, fmt.Errorf("器具编号 %s：%w", instID, ErrNotFound)
339		}
340	
341		_, calText, err := parseFiniteDate(in.CalDate, "校准日期")
342		if err != nil {
343			return nil, false, err
344		}
345		_, expText, err := parseFiniteDate(in.Expiry, "有效期截止日")
346		if err != nil {
347			return nil, false, err
348		}
349		// 与“本机今天”按日历日期比较，避免时分秒和时区造成边界误差。
350		todayText := l.now().Format(DateLayout)
351		if calText > todayText {
352			return nil, false, validationError("校准日期 %s 不能晚于本机今天 %s", calText, todayText)
353		}
354		if expText <= calText {
355			return nil, false, validationError("有效期截止日 %s 必须晚于校准日期 %s", expText, calText)
356		}
357	
358		if existing := l.findCertificate(number); existing != nil {
359			same := existing.InstrumentID == instID &&
360				existing.CalDate == calText &&
361				existing.Expiry == expText &&
362				existing.Method == method &&
363				existing.Summary == summary &&
364				existing.Error == in.Error
365			if !same {
366				return nil, false, &ConflictError{Msg: fmt.Sprintf(
367					"证书编号 %s 已存在且内容不同，拒绝覆盖已有数据", number)}
368			}
369			// 同号且全部业务字段一致：返回原证书，不增加历史记录。
370			return existing, true, nil
371		}
372	
373		// 同一器具同一天不接受两张不同编号的证书。
374		for i := range l.data.Certificates {
375			c := &l.data.Certificates[i]
376			if c.InstrumentID == instID && c.CalDate == calText {
377				return nil, false, validationError(
378					"器具 %s 在 %s 已有证书 %s，同一天不能再登记不同编号的证书",
379					instID, calText, c.Number)
380			}
381		}
382	
383		cert := Certificate{
384			Number:       number,
385			InstrumentID: instID,
386			CalDate:      calText,
387			Expiry:       expText,
388			Method:       method,
389			Error:        in.Error,
390			Summary:      summary,
391			CreatedAt:    l.now().Format(time.RFC3339),
392		}
393		l.data.Certificates = append(l.data.Certificates, cert)
394		if err := l.save(); err != nil {
395			return nil, false, err
396		}
397		return l.findCertificate(number), false, nil
398	}
399	
400	// certificatesOf 返回某器具的证书，按校准日期从新到旧排序；日期相同时
401	// （实际业务不会允许同日多证）以证书编号排序保证结果稳定。
402	func (l *Ledger) certificatesOf(id string) []Certificate {
403		var out []Certificate
404		for _, c := range l.data.Certificates {
405			if c.InstrumentID == id {
406				out = append(out, c)
407			}
408		}
409		sort.Slice(out, func(i, j int) bool {
410			if out[i].CalDate != out[j].CalDate {
411				return out[i].CalDate > out[j].CalDate
412			}
413			return out[i].Number < out[j].Number
414		})
415		return out
416	}
417	
418	// LatestCertificate 返回器具按校准日期确定的最近证书；没有证书时返回 nil。
419	// 最近证书与录入先后无关，补录较早证书只增加历史。
420	func (l *Ledger) LatestCertificate(id string) *Certificate {
421		cs := l.certificatesOf(id)
422		if len(cs) == 0 {
423			return nil
424		}
425		return &cs[0]
426	}
427	
428	// CertificateView 是证书及其在当前日期下的判定结果。
429	type CertificateView struct {
430		Certificate
431		Pass    bool `json:"pass"`
432		Expired bool `json:"expired"`
433	}
434	
435	func viewCertificate(c Certificate, allowed float64, today time.Time) CertificateView {
436		return CertificateView{
437			Certificate: c,
438			Pass:        c.Pass(allowed),
439			// 有效期截止日当天起即到期：按日历日期比较，今天 >= 截止日即为到期。
440			Expired: today.Format(DateLayout) >= c.Expiry,
441		}
442	}
443	
444	// UsageDecision 是一次使用申请的评估结果，原因在申请时冻结留痕。
445	type UsageDecision struct {
446		InstrumentID string
447		Allowed      bool
448		Reasons      []string
449		Latest       *CertificateView
450		evaluatedAt  time.Time
451	}
452	
453	// evaluate 按器具状态与“最近证书”判定当前能否使用，并列出全部适用原因。
454	// 最近证书超差或到期时不会回退到更早的合格证书。
455	func (l *Ledger) evaluate(id string) (*Instrument, *UsageDecision) {
456		today := l.now()
457		inst := l.findInstrument(id)
458		if inst == nil {
459			return nil, nil
460		}
461		d := &UsageDecision{InstrumentID: id, evaluatedAt: today}
462		if inst.Status != StatusInUse {
463			d.Reasons = append(d.Reasons, fmt.Sprintf("器具当前状态为%s，只有在用器具可以申请使用", inst.Status))
464		}
465		latest := l.LatestCertificate(id)
466		if latest == nil {
467			d.Reasons = append(d.Reasons, "没有校准证书")
468		} else {
469			v := viewCertificate(*latest, inst.AllowedError, today)
470			d.Latest = &v
471			if !v.Pass {
472				d.Reasons = append(d.Reasons, fmt.Sprintf(
473					"最近证书 %s 测得误差绝对值 %g 超过允许误差 %g，判定超差",
474					latest.Number, math.Abs(latest.Error), inst.AllowedError))
475			}
476			if v.Expired {
477				d.Reasons = append(d.Reasons, fmt.Sprintf("最近证书 %s 已于 %s 到期（截止日当天即到期）",
478					latest.Number, latest.Expiry))
479			}
480		}
481		d.Allowed = len(d.Reasons) == 0
482		return inst, d
483	}
484	
485	// CanUse 只按当前数据评估能否使用，不留存申请记录。
486	func (l *Ledger) CanUse(id string) (*UsageDecision, error) {
487		inst, d := l.evaluate(id)
488		if inst == nil {
489			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
490		}
491		return d, nil
492	}
493	
494	// RequestUse 针对已有器具提交使用申请：无论允许或拒绝都保存申请时间、结果
495	// 与当时全部原因。未知编号报错且不新增记录。
496	func (l *Ledger) RequestUse(id string) (*UsageDecision, error) {
497		if strings.TrimSpace(id) == "" {
498			return nil, fmt.Errorf("器具编号无效：%w", validationError("不能留空或只有空白"))
499		}
500		inst, d := l.evaluate(id)
501		if inst == nil {
502			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
503		}
504		rec := UsageRecord{
505			InstrumentID: id,
506			RequestedAt:  d.evaluatedAt.Format(time.RFC3339),
507			Allowed:      d.Allowed,
508			Reasons:      d.Reasons,
509		}
510		if rec.Reasons == nil {
511			rec.Reasons = []string{}
512		}
513		l.data.Usage = append(l.data.Usage, rec)
514		if err := l.save(); err != nil {
515			return nil, err
516		}
517		return d, nil
518	}
519	
520	// InstrumentReview 是按器具核对的完整视图。
521	type InstrumentReview struct {
522		Instrument Instrument        `json:"instrument"`
523		CanUse     bool              `json:"can_use"`
524		Reasons    []string          `json:"reasons"`
525		Latest     *CertificateView  `json:"latest"`
526		History    []CertificateView `json:"history"`
527		Rejections []UsageRecord     `json:"rejections"`
528	}
529	
530	// Review 按器具核对：登记信息、当前能否使用及原因、最近证书与到期日、
531	// 全部历史证书以及被拒绝的使用记录。历史拒绝原因按申请当时的冻结内容展示，
532	// 不随后来补录证书或切换状态而改变。
533	func (l *Ledger) Review(id string) (*InstrumentReview, error) {
534		inst, d := l.evaluate(id)
535		if inst == nil {
536			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
537		}
538		r := &InstrumentReview{
539			Instrument: *inst,
540			CanUse:     d.Allowed,
541			Reasons:    d.Reasons,
542			Latest:     d.Latest,
543		}
544		if r.Reasons == nil {
545			r.Reasons = []string{}
546		}
547		today := l.now()
548		for _, c := range l.certificatesOf(id) {
549			r.History = append(r.History, viewCertificate(c, inst.AllowedError, today))
550		}
551		for _, u := range l.data.Usage {
552			if u.InstrumentID == id && !u.Allowed {
553				r.Rejections = append(r.Rejections, u)
554			}
555		}
556		return r, nil
557	}
558	
559	// Instruments 返回全部登记器具的副本，按编号排序。
560	func (l *Ledger) Instruments() []Instrument {
561		out := append([]Instrument(nil), l.data.Instruments...)
562		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
563		return out
564	}
565	
566	// UsageRecords 返回全部使用申请记录，按申请时间排序。
567	func (l *Ledger) UsageRecords() []UsageRecord {
568		out := append([]UsageRecord(nil), l.data.Usage...)
569		sort.SliceStable(out, func(i, j int) bool {
570			if out[i].RequestedAt != out[j].RequestedAt {
571				return out[i].RequestedAt < out[j].RequestedAt
572			}
573			return out[i].InstrumentID < out[j].InstrumentID
574		})
575		return out
576	}
577

