// failPlanBusiness 是计划类命令共用的业务拒绝输出（退出码 1）。
func failPlanBusiness(opts options, stdout, stderr io.Writer, err error, extra map[string]any) int {
	resp := map[string]any{"accepted": false, "error": err.Error()}
	for k, v := range extra {
